}
# set_owner PATH OWNER GROUP: change ownership if OWNER or GROUP are given
set_owner() {
  if [ -n "$2" ] && [ -n "$3" ]; then chown "$2:$3" "$1"
  elif [ -n "$2" ]; then chown "$2" "$1"
  elif [ -n "$3" ]; then chgrp "$3" "$1"
