}
# ensure_line FILE LINE [REGEX]: make sure LINE is in FILE; replace lines matching REGEX
ensure_line() {
  [ -f "$1" ] || { mkdir -p "$(dirname "$1")"; : > "$1"; }
  if [ -n "${3:-}" ] && grep -Eq -- "$3" "$1"; then
    osb_tmp=$(mktemp)
